SCRUBBED PROGRAM:
from collections import deque

def solve(grid, start, goal):
    if not grid or not 0 <= start[0] < len(grid) or (not 0 <= start[1] < len(grid[0])) or (not 0 <= goal[0] < len(grid)) or (not 0 <= goal[1] < len(grid[0])) or (grid[start[0]][start[1]] == '#') or (grid[goal[0]][goal[1]] == '#'):
        return []
    if start == goal:
        return [start]
    rows, cols = (len(grid), len(grid[0]))
    visited = [[False] * cols for _ in range(rows)]
    parent = {}
    queue = deque()
    queue.append(start)
    visited[start[0]][start[1]] = True
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    while queue:
        current = queue.popleft()
        if current == goal:
            path = []
            while current:
                path.append(current)
                current = parent.get(current)
            return path[::-1]
        for dr, dc in directions:
            nr, nc = (current[0] + dr, current[1] + dc)
            if 0 <= nr < rows and 0 <= nc < cols and (not visited[nr][nc]) and (grid[nr][nc] == '.'):
                visited[nr][nc] = True
                parent[nr, nc] = current
                queue.append((nr, nc))
    return []

