    rows, cols = (len(grid), len(grid[0]))
    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    if not (0 <= start[0] < rows and 0 <= start[1] < cols) or not (0 <= goal[0] < rows and 0 <= goal[1] < cols) or grid[start[0]][start[1]] == '#' or (grid[goal[0]][goal[1]] == '#'):
        return []
    visited = set()
    frontier = [(0, 0, start)]
    parent = {}
    counter = 1
    while frontier:
        steps, _, current = heapq.heappop(frontier)
        if current in visited:
            continue
        visited.add(current)
        if current == goal:
            path = []
            while current in parent:
                path.append(current)
                current = parent[current]
            path.append(start)
            return path[::-1]
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = (current[0] + dr, current[1] + dc)
            if 0 <= nr < rows and 0 <= nc < cols and (grid[nr][nc] == '.') and ((nr, nc) not in visited):
                heapq.heappush(frontier, (steps + 1, counter, (nr, nc)))
                if (nr, nc) not in parent:
                    parent[nr, nc] = current
                    counter += 1
    return []

